lobWrapper" style="padding-top:8px;padding-bottom:8px"><div id="highlighted-line-menu-positioner" class="position-relative"><div id="copilot-button-positioner" class="position-relative"><div class="CodeBlob-module_R1veHa_codeBlobInner"><div class="CodeBlob-module_R1veHa_cursorContainer"><div style="height: 5180px;"><div aria-hidden="true" data-testid="navigation-cursor" class="NavigationCursor-module_cWbSOW_codeNavigationCursor" style="top: 0px; left: 92px;"> </div></div></div><div style="display: contents;"><div style="display: contents;"><textarea id="read-only-cursor-text-area" data-testid="read-only-cursor-text-area" aria-label="file content" aria-readonly="true" inputmode="none" tabindex="0" aria-multiline="true" aria-haspopup="false" data-gramm="false" data-gramm_editor="false" data-enable-grammarly="false" spellcheck="false" autocorrect="off" autocapitalize="off" autocomplete="off" data-ms-editor="false" class="TextArea-module_jn40_W_reactBlobTextarea react-blob-print-hide" style="resize: none; margin-top: -2px; padding-left: 92px; padding-right: 70px; width: 100%; background-color: unset; box-sizing: border-box; color: transparent; position: absolute; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; tab-size: 4; outline: none; overflow: auto hidden; height: 5200px; font-size: 12px; line-height: 20px; overflow-wrap: normal; overscroll-behavior-x: none; white-space: pre; z-index: 1;">create database raceDay;
 
 
 

create table Users (
usersID int IDENTITY(1,1), 
Email varchar(50)unique,
userName varchar(50),
role varchar(50),
AccountType varchar(20)not null,

Constraint PK_Users_usersID PRIMARY KEY(usersID),
Constraint UQ_Users_userName unique(userName),
constraint UQ_Users_Email unique(Email)
 
);

create table Organiser(
organiserID int,
organiserNumber int not null,
usersID int NOT NULL,
 

constraint PK_Organiser_organiserID PRIMARY KEY(organiserID),
constraint UK_Organiser_usersID UNIQUE(usersID),
constraint FK_Organiser_Users foreign key(usersID) references Users(usersID)
ON DELETE NO ACTION

);

create table Participant(
participantID int ,
participantName varchar(50)not null,
usersID int NOT NULL,
 
Constraint PK_Participant_participantID PRIMARY KEY(participantID),
constraint UK_Participant_usersID UNIQUE(usersID),
constraint FK_Participant_Users foreign key(usersID) references Users(usersID)
ON DELETE NO ACTION


);

create table Events(
eventID int,  
eventName varchar(50)not null,
eventDate DATE NOT NULL,
description VARCHAR(255),
location varchar(100)not null,
organiserID int not null,
 
constraint PK_Events_eventID PRIMARY KEY(eventID),
constraint FK_Events_Organiser foreign key(organiserID) references Organiser(organiserID)
ON DELETE NO ACTION

);

create table Category(
categoryID int,
categoryName varchar(50)not null,
eventID int not null,
 
 constraint PK_Category_categoryID PRIMARY KEY(categoryID)
);

CREATE TABLE Result(
 resultID INT NOT NULL,
 participantID INT NOT NULL,
 eventID INT NOT NULL,
 finishingTime TIME NOT NULL,
 position INT NOT NULL,
    CONSTRAINT PK_Result_resultID 
        PRIMARY KEY(resultID),
    CONSTRAINT FK_Result_Participant
        FOREIGN KEY(participantID)
        REFERENCES Participant(participantID),
    CONSTRAINT FK_Result_Event
        FOREIGN KEY(eventID)
        REFERENCES Events(eventID)
);
create table route(
RouteID INT IDENTITY(1,1),
EventID int not null,
RouteName varchar (100)not null,
distance decimal(6,2) not null,

 Constraint PK_route_RouteID PRIMARY KEY(RouteID),
 Constraint FK_Events_eventID foreign key(eventID) references Events(eventID)
 ON DELETE NO ACTION

);

CREATE TABLE entry(
    EntryID INT IDENTITY(1,1) NOT NULL,
    ParticipantID INT NOT NULL,
    EventID INT NOT NULL,
    PRICE DECIMAL(10,2) NOT NULL,

    CONSTRAINT PK_Entry_EntryID 
        PRIMARY KEY(EntryID),

    CONSTRAINT UK_Entry_Participant_Events 
        UNIQUE(EventID, ParticipantID),

    CONSTRAINT FK_Entry_Participant
        FOREIGN KEY(ParticipantID)
        REFERENCES Participant(ParticipantID)
        ON DELETE NO ACTION,

    CONSTRAINT FK_Entry_Event
        FOREIGN KEY(EventID)
        REFERENCES Events(EventID)
        ON DELETE NO ACTION
);

 

  

